package com.pharmapack.qms.capa; import com.pharmapack.qms.audit.AuditTrailService; import com.pharmapack.qms.deviation.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/capa") public class CapaController { final CapaRepository cr; final DeviationRepository dr; final AuditTrailService at; public CapaController(CapaRepository c,DeviationRepository d,AuditTrailService a){cr=c;dr=d;at=a;} @GetMapping public List<CapaActionResponse> list(){return cr.findAll().stream().map(this::dto).toList();} public record Create(Long deviationId,String actionType,String actionDescription,Long ownerId,LocalDate dueDate){}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public CapaActionResponse create(@RequestBody Create x){CapaAction c=new CapaAction();c.setDeviation(dr.findById(x.deviationId()).orElseThrow(()->new IllegalArgumentException("Deviation not found")));c.setActionType(x.actionType());c.setActionDescription(x.actionDescription());c.setOwnerId(x.ownerId());c.setDueDate(x.dueDate());CapaAction saved=cr.save(c);at.log("CREATE","CapaAction",saved.getId(),"actionType",null,saved.getActionType());return dto(cr.findById(saved.getId()).orElseThrow());}
 CapaActionResponse dto(CapaAction c){var dv=c.getDeviation();var b=dv==null?null:dv.getBatch();return new CapaActionResponse(c.getId(),dv==null?null:dv.getId(),dv==null?null:dv.getDeviationNumber(),b==null?null:b.getId(),b==null?null:b.getBatchNumber(),b==null?null:b.getProduct().getProductCode(),b==null?null:b.getProduct().getProductName(),c.getActionType(),c.getActionDescription(),c.getOwnerId(),c.getDueDate(),c.getCompletedDate(),c.getStatus(),c.getEffectivenessResult());}
}
